// src/services/ticket-persistence.js
import { Types } from 'mongoose';
import { Ticket } from '../models/Ticket.js';

/**
 * Ensures event tickets exist in MongoDB for scanner reconciliation.
 * Designed for virtual orders generated by season ticket scripts.
 *
 * @param {Object} opts
 * @param {Object} opts.event            - Event document (needs _id/seasonCode/venueSlug).
 * @param {Object} opts.virtualOrder     - Synthetic order carrying lines + meta.tickets.
 * @param {import('mongoose').Types.ObjectId|string|null} [opts.sourceOrderId]
 * @param {Date}   [opts.now]
 * @returns {Promise<{created:number, updated:number, skipped:number}>}
 */
export async function upsertEventTickets({
  event,
  virtualOrder,
  sourceOrderId = null,
  now = new Date()
} = {}) {
  if (!event || !event._id) {
    throw new Error('upsertEventTickets: event with _id is required');
  }
  if (!virtualOrder || !virtualOrder.meta || !Array.isArray(virtualOrder.meta.tickets)) {
    return { created: 0, updated: 0, skipped: 0 };
  }

  const ticketsMeta = virtualOrder.meta.tickets;
  if (!ticketsMeta.length) {
    return { created: 0, updated: 0, skipped: 0 };
  }

  const lines = Array.isArray(virtualOrder.lines) ? virtualOrder.lines : [];
  const seasonCode = virtualOrder.seasonCode || event.seasonCode || '';
  const venueSlug = virtualOrder.venueSlug || event.venueSlug || '';
  const eventId = String(event._id);

  const orderId =
    sourceOrderId instanceof Types.ObjectId
      ? sourceOrderId
      : (Types.ObjectId.isValid(sourceOrderId) ? new Types.ObjectId(sourceOrderId) : null);

  let created = 0;
  let updated = 0;
  let skipped = 0;

  for (let i = 0; i < ticketsMeta.length; i++) {
    const metaTicket = ticketsMeta[i] || {};
    const line = lines[i] || {};
    const qrValue = String(metaTicket.hex || metaTicket.value || '').trim();
    if (!qrValue) {
      skipped++;
      continue;
    }

    const zoneKeyRaw = String(metaTicket.zoneKey || line.zoneKey || '').trim().toUpperCase();
    const seatCandidate = String(metaTicket.seatId || line.seatId || '').trim();
    const fallbackSeat = (() => {
      const zone = zoneKeyRaw || 'ZONE';
      const suffixSource = orderId ? String(orderId) : eventId;
      const suffix = suffixSource.slice(-6).toUpperCase();
      const index = String(i + 1).padStart(2, '0');
      return `${zone}-GA-${suffix}-${index}`;
    })();
    const seatId = seatCandidate || fallbackSeat;

    const tariffCode = String(line.tariffCode || metaTicket.tariff || metaTicket.tariffCode || '')
      .trim()
      .toUpperCase();

    const holderFirst = String(line.holderFirstName || metaTicket.holderFirstName || '').trim();
    const holderLast = String(line.holderLastName || metaTicket.holderLastName || '').trim();
    const holderEmail = String(
      line.holderEmail ||
      metaTicket.holderEmail ||
      virtualOrder.payerEmail ||
      ''
    ).trim();

    const setDoc = {
      seasonCode,
      venueSlug,
      eventId,
      seatId,
      tariffCode,
      'holder.firstName': holderFirst,
      'holder.lastName': holderLast,
      'holder.email': holderEmail,
      'qr.value': qrValue,
      'qr.kind': 'text'
    };
    if (orderId) setDoc.orderId = orderId;
    if (metaTicket.bankId) setDoc['qr.bankId'] = metaTicket.bankId;

    const setOnInsert = {
      'qr.createdAt': metaTicket.createdAt ? new Date(metaTicket.createdAt) : now,
      scanCount: 0,
      scanHistory: []
    };

    try {
      const result = await Ticket.updateOne(
        { 'qr.value': qrValue },
        { $set: setDoc, $setOnInsert: setOnInsert },
        { upsert: true }
      );
      if (result?.upsertedCount) created += 1;
      else if (result?.modifiedCount) updated += 1;
      else skipped += 1;
    } catch (err) {
      // Duplicate key (race) fallback: attempt reread to confirm existence
      if (err?.code === 11000) {
        const existing = await Ticket.findOne({ 'qr.value': qrValue }).lean();
        if (existing) {
          skipped += 1;
          continue;
        }
      }
      throw err;
    }
  }

  return { created, updated, skipped };
}
